<template>
	<view class="add-bill">
		<view class="bill_details" v-if="billData">
			<view class="bill_type">
				{{ ['支出','收入','转账','预交款'][billData.type] }}
			</view>
			<view class="bill_warpper">
				<view class="bill_amount">
					¥ {{ Number(billData.amount).toFixed(2) }}
				</view>
				<view class="bill_date">
					今天
				</view>
			</view>
		</view>
		<view class="icon_warpper">
			<view class="icon_for" @click="iconSecelt(item)" :class="{ isActive: iconActive == item.icon }"
				v-for="(item, index) in iconData" :key="index">
				<SvgIcon class="icon_svg" width="50px" height="50px"
					:name="iconActive == item.icon?`${item.icon}-hover`:item.icon" />
				<text class="icon_text">{{ item.text }}</text>
			</view>
		</view>
		<view class="bill_footer">
			<view class="bill_submit" @click="submit()">
				确认
			</view>
		</view>
	</view>
</template>

<script>
	import SvgIcon from '../component/svg-icon.vue' // 引入svg
	export default {
		data() {
			return {
				billData: null,
				iconData: [],
				iconActive: '',
				textActive: '',
			}
		},
		components: {
			SvgIcon,
		},
		onShow: function() {
			const IconData = getApp().globalData.iconArray;
			console.log(IconData);
			this.iconData = IconData
			const data = getApp().globalData.billCount;
			console.log(data);
			this.billData = data
			// 清除数据，避免下次读取错误
			getApp().globalData.billCount = null;
		},
		methods: {
			iconSecelt(item) {
				this.iconActive = item.icon
				this.textActive = item.text
			},
			submit() {
				// 在源页面存储数据
				getApp().globalData.selectBillData = {
					...this.billData,
					icon: this.iconActive,
					text: this.textActive
				};
				uni.switchTab({
					url: `/pages/index/index`
				});
			}
		}
	}
</script>

<style scoped lang="scss">
	.add-bill {
		width: 100%;
		position: relative;

		.bill_details {
			padding: 20px;
			box-sizing: border-box;
			border-bottom: 5px solid #eee;

			.bill_type {
				font-size: 16px;
				color: #999;
			}

			.bill_warpper {
				display: flex;
				align-items: center;
				justify-content: space-between;
				box-sizing: border-box;
				margin-top: 10px;

				.bill_amount {
					color: #55c9c9;
					font-size: 30px;
					font-weight: bold;
				}
			}
		}

		.icon_warpper {
			width: 100%;
			display: grid;
			grid-template-columns: repeat(auto-fill, minmax(50px, 1fr));
			grid-gap: 23px 45px;
			justify-items: center;
			// #ifdef MP-WEIXIN 
			padding: 20px 20px calc(80px + env(safe - area - inset - bottom));
			// #endif 
			// #ifndef MP-WEIXIN 
			padding: 20px 20px 80px;
			// #endif 
			box-sizing: border-box;

			.icon_for {
				width: 50px;
				display: grid;

				&:deep(.svg-icon) {
					background: #eee;
					padding: 10px;
					border-radius: 50%;
					box-sizing: border-box;
				}

				.icon_text {
					display: block;
					width: 100%;
					margin-top: 5px;
					font-size: 14px;
					color: #333;
					text-align: center;
					height: 18px;
					line-height: 18px;
				}
			}

			.isActive {
				&:deep(.svg-icon) {
					background: #55c9c9;
				}

				.icon_text {
					color: #55c9c9;
				}
			}
		}

		.bill_footer {
			width: 100%;
			position: fixed;
			bottom: 0;
			left: 0;
			background: #fff;
			box-shadow: 0 0 10px #aaa;
			box-sizing: border-box;
			// #ifdef MP-WEIXIN 
			padding: 10px 20px calc(0px + env(safe - area - inset - bottom));
			// #endif 
			// #ifndef MP-WEIXIN 
			padding: 10px 20px;
			// #endif 

			.bill_submit {
				background: #55c9c9;
				color: #fff;
				height: 50px;
				text-align: center;
				border-radius: 5px;
				line-height: 50px;
				font-size: 20px;
				font-weight: bold;
			}
		}
	}
</style>